/** The section's dawn, rasterized once per layout for all three glass lenses. */
function featureBackdrop(
  width: number,
  height: number,
  line: number,
  accent: string,
  soft: string,
) {
  const attribute = (value: string) =>
    value.replaceAll('&', '&amp;').replaceAll('"', '&quot;').replaceAll('<', '&lt;');

  const aqua = attribute(accent);
  const pale = attribute(soft);

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
    <defs>
      <linearGradient id="night" x2="0" y2="1"><stop stop-color="#0f1628"/><stop offset=".36" stop-color="#0e1424"/></linearGradient>
      <radialGradient id="aqua" gradientUnits="userSpaceOnUse" cx="0" cy="0" r="1" gradientTransform="translate(${width * 0.14} ${height * 0.56}) scale(${width * 0.36} ${height * 0.3})"><stop stop-color="${aqua}" stop-opacity=".17"/><stop offset=".72" stop-color="${aqua}" stop-opacity="0"/></radialGradient>
      <radialGradient id="rose" gradientUnits="userSpaceOnUse" cx="0" cy="0" r="1" gradientTransform="translate(${width * 0.88} ${height * 0.7}) scale(${width * 0.32} ${height * 0.28})"><stop stop-color="#ffb38a" stop-opacity=".14"/><stop offset=".72" stop-color="#ffb38a" stop-opacity="0"/></radialGradient>
      <pattern id="lines" width="${width}" height="9" x="0" y="${height * 0.22}" patternUnits="userSpaceOnUse"><rect width="${width}" height="1" fill="#bef0f5" fill-opacity=".09"/></pattern>
      <radialGradient id="fade" gradientUnits="userSpaceOnUse" cx="0" cy="0" r="1" gradientTransform="translate(${width * 0.5} ${height * 0.6048}) scale(${width * 0.72} ${height * 0.4588})"><stop offset=".28" stop-color="white"/><stop offset=".76" stop-color="white" stop-opacity="0"/></radialGradient>
      <mask id="grid-fade"><rect width="${width}" height="${height}" fill="url(#fade)"/></mask>
      <radialGradient id="dawn-rose" gradientUnits="userSpaceOnUse" cx="0" cy="0" r="1" gradientTransform="translate(${width * 0.5} ${line}) scale(${width * 0.38} 101.2)"><stop stop-color="#ffb38a" stop-opacity=".17"/><stop offset=".72" stop-color="#ffb38a" stop-opacity="0"/></radialGradient>
      <radialGradient id="dawn-aqua" gradientUnits="userSpaceOnUse" cx="0" cy="0" r="1" gradientTransform="translate(${width * 0.5} ${line}) scale(${width * 0.64} 66)"><stop stop-color="${aqua}" stop-opacity=".17"/><stop offset=".76" stop-color="${aqua}" stop-opacity="0"/></radialGradient>
      <linearGradient id="horizon"><stop offset=".01" stop-color="${pale}" stop-opacity="0"/><stop offset=".18" stop-color="${pale}" stop-opacity=".6"/><stop offset=".5" stop-color="#fff2ea"/><stop offset=".82" stop-color="${pale}" stop-opacity=".6"/><stop offset=".99" stop-color="${pale}" stop-opacity="0"/></linearGradient>
      <filter id="glow" x="-10%" y="-1000%" width="120%" height="2100%"><feGaussianBlur stdDeviation="11"/></filter>
    </defs>
    <rect width="100%" height="100%" fill="url(#night)"/>
    <rect width="100%" height="100%" fill="url(#aqua)"/>
    <rect width="100%" height="100%" fill="url(#rose)"/>
    <rect y="${height * 0.22}" width="${width}" height="${height * 0.74}" fill="url(#lines)" mask="url(#grid-fade)"/>
    <rect y="${line - 110}" width="${width}" height="220" fill="url(#dawn-rose)"/>
    <rect y="${line - 110}" width="${width}" height="220" fill="url(#dawn-aqua)"/>
    <rect y="${line - 3}" width="${width}" height="7" fill="${aqua}" fill-opacity=".3" filter="url(#glow)"/>
    <rect y="${line}" width="${width}" height="1" fill="url(#horizon)"/>
  </svg>`;

  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
}

/**
 * A dawn line runs behind the tiles where the first tile's screen meets its copy, so every lens
 * rim has a horizon to bend.
 */
export function FeatureTiles() {
  const sectionRef = useRef<HTMLElement>(null);
  const sceneRef = useRef<HTMLDivElement>(null);
  const gridRef = useRef<HTMLDivElement>(null);

  const [backdrop, setBackdrop] = useState(() =>
    featureBackdrop(1200, 1000, 580, '#3ad1e0', '#a6eaf1'),
  );

  useEffect(() => {
    const section = sectionRef.current;
    const scene = sceneRef.current;
    const grid = gridRef.current;
    const tile = grid?.firstElementChild;
    const screen = tile?.querySelector<HTMLElement>('.halcyon-tile-screen');

    if (!section || !scene || !grid || !(tile instanceof HTMLElement) || !screen) return;

    let frame = 0;

    // Offsets ignore the tiles' rise transform, so the line stays put while they move.
    const layout = () => {
      let line = screen.offsetTop + screen.offsetHeight + 12;

      for (
        let parent = screen.offsetParent;
        parent instanceof HTMLElement && parent !== scene;
        parent = parent.offsetParent
      ) {
        line += parent.offsetTop;
      }

      section.style.setProperty('--halcyon-what-line', `${line}px`);
      const style = getComputedStyle(section);
      setBackdrop(
        featureBackdrop(
          section.clientWidth,
          section.clientHeight,
          line,
          style.getPropertyValue('--hc-accent').trim(),
          style.getPropertyValue('--hc-accent-soft').trim(),
        ),
      );
    };

    const observer = new ResizeObserver(() => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(layout);
    });

    observer.observe(section);
    layout();

    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, []);

  return (
    <section
      ref={sectionRef}
      aria-labelledby="halcyon-what-title"
      className="halcyon-what"
      id="what"
    >
      <GlassScene
        ref={sceneRef}
        backdrop={backdrop}
        className="halcyon-what-scene"
        optics={{
          bevel: 30,
          thickness: 42,
          ior: 1.5,
          dispersion: 0.16,
          frost: 6,
          specular: 1,
          merge: 0,
        }}
      >
        <div aria-hidden className="halcyon-what-art">
          <div className="halcyon-what-horizon" />
        </div>
        <div className="halcyon-wrap">
          <header className="halcyon-section-head">
            <p className="halcyon-eyebrow">In your calendar from January</p>
            <h2 className="halcyon-section-title halcyon-reveal-text" id="halcyon-what-title">
              Three jobs, done <em>quietly</em>.
            </h2>
            <p className="halcyon-section-lede">
              Halcyon works inside the calendar you already use. It takes care of the logistics and
              leaves the decisions to you.
            </p>
          </header>
          <div ref={gridRef} className="halcyon-what-grid">
            <BooksTile />
            <MovesTile />
            <ProtectsTile />
          </div>
        </div>
      </GlassScene>
    </section>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';
import { GlassPanel } from '../../glass-panel';
import { motionReduced } from '../../lib/liquid-motion';

const UNITS = ['days', 'hours', 'minutes', 'seconds'] as const;

function partsUntil(target: number, now: number) {
  const seconds = Math.floor(Math.max(0, target - now) / 1000);

  return [
    Math.floor(seconds / 86400),
    Math.floor(seconds / 3600) % 24,
    Math.floor(seconds / 60) % 60,
    seconds % 60,
  ];
}

/**
 * One digit that rolls up to its next value. The roll plays only while the countdown is on
 * screen and motion is allowed; otherwise the digit changes in place.
 */
function Digit({ value, roll }: { value: string; roll: boolean }) {
  const [shown, setShown] = useState<{ current: string; previous: string | null; turn: number }>({
    current: value,
    previous: null,
    turn: 0,
  });

  if (shown.current !== value) {
    setShown({
      current: value,
      previous: roll ? shown.current : null,
      turn: shown.turn + 1,
    });
  }

  return (
    <span className="halcyon-countdown-slot">
      {shown.previous !== null ? (
        <span key={`out-${shown.turn}`} className="halcyon-countdown-out">
          {shown.previous}
        </span>
      ) : null}
      <span
        key={`in-${shown.turn}`}
        className={shown.previous !== null ? 'halcyon-countdown-in' : undefined}
      >
        {shown.current}
      </span>
    </span>
  );
}

/**
 * Days, hours, minutes and seconds until `target`, in the visitor's own time. The time is read
 * after the page loads, so a page built ahead of time never shows a stale count.
 */
export function Countdown({ target, labelledBy }: { target: Date; labelledBy: string }) {
  const rootRef = useRef<HTMLDivElement>(null);
  const [now, setNow] = useState<number | null>(null);
  const [onScreen, setOnScreen] = useState(false);
  const time = target.getTime();

  useEffect(() => {
    let timer = 0;

    const tick = () => {
      const current = Date.now();

      setNow(current);

      // Each tick lands just after the second turns, so the digits change together.
      if (current < time) timer = window.setTimeout(tick, 1000 - (current % 1000) + 8);
    };

    tick();

    return () => window.clearTimeout(timer);
  }, [time]);

  useEffect(() => {
    const root = rootRef.current;

    if (!root) return;

    const observer = new IntersectionObserver(([entry]) => setOnScreen(entry.isIntersecting));

    observer.observe(root);

    return () => observer.disconnect();
  }, []);

  const parts = now === null ? null : partsUntil(time, now);
  const roll = onScreen && !motionReduced();

  const summary =
    parts === null
      ? ''
      : now !== null && now >= time
        ? 'Invites are going out now.'
        : `${parts[0]} days, ${parts[1]} hours and ${parts[2]} minutes until invites begin.`;

  return (
    <div
      ref={rootRef}
      aria-describedby="halcyon-countdown-summary"
      aria-labelledby={labelledBy}
      className="halcyon-countdown"
      role="timer"
    >
      {UNITS.map((unit, index) => {
        const digits = parts === null ? '––' : String(parts[index]).padStart(2, '0');

        return (
          <GlassPanel
            key={unit}
            className="halcyon-pane halcyon-countdown-unit"
            lens
            variant="card"
          >
            <span aria-hidden className="halcyon-countdown-value">
              {[...digits].map((digit, place) => (
                <Digit key={place} roll={roll} value={digit} />
              ))}
            </span>
            <span aria-hidden className="halcyon-countdown-label">
              {unit}
            </span>
          </GlassPanel>
        );
      })}
      {/* Announced once a minute at most: the summary leaves the seconds out. */}
      <p className="halcyon-sr-only" id="halcyon-countdown-summary">
        {summary}
      </p>
    </div>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';
import { motionReduced } from '../../lib/liquid-motion';
import { useCountTo } from './use-count-to';

type StatCounterProps = {
  /** The figure, or minutes when shown as hours and minutes. */
  count: number;
  /** Where the count starts when the figure scrolls into view. */
  from: number;
  /** What the figure measures; read first by screen readers. */
  label: string;
  /** What screen readers hear for the figure, such as "3 hours 50 minutes". */
  spoken: string;
  hoursAndMinutes?: boolean;
};

/**
 * A figure that counts up once, when it first scrolls into view. Figures already on screen,
 * and every figure under reduced motion, show their value from the start.
 */
export function StatCounter({ count, from, label, spoken, hoursAndMinutes }: StatCounterProps) {
  const figureRef = useRef<HTMLSpanElement>(null);
  const [stage, setStage] = useState<'shown' | 'waiting' | 'counting'>('shown');

  const value = useCountTo(
    stage === 'waiting' ? from : count,
    1400,
    stage === 'shown' ? undefined : from,
    120,
  );

  useEffect(() => {
    const figure = figureRef.current;

    if (!figure || motionReduced() || figure.getBoundingClientRect().top < window.innerHeight) {
      return;
    }

    setStage('waiting');

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return;

        observer.disconnect();
        setStage('counting');
      },
      { threshold: 0.9 },
    );

    observer.observe(figure);

    return () => observer.disconnect();
  }, []);

  return (
    <div className="halcyon-stat">
      <dt>{label}</dt>
      <dd>
        <span ref={figureRef} aria-hidden className="halcyon-stat-figure">
          {hoursAndMinutes ? (
            <>
              {Math.floor(value / 60)}
              <span className="halcyon-stat-unit">h</span>
              {String(value % 60).padStart(2, '0')}
              <span className="halcyon-stat-unit">min</span>
            </>
          ) : (
            value.toLocaleString('en-GB')
          )}
        </span>
        <span className="halcyon-sr-only">{spoken}</span>
      </dd>
    </div>
  );
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

type Ray = { height: number; opacity: number; width: number; x: number; y: number };

type Star = { big: boolean; opacity: number; radius: number; x: number; y: number };

type Art = { rays: Ray[]; stars: Star[]; width: number; horizon: number };

// The aurora's curve across a 1440 x 600 band: M0 150 C380 250 560 338 720 338 S1100 260 1440 170.
const CURVE = [
  [
    [0, 150],
    [380, 250],
    [560, 338],
    [720, 338],
  ],
  [
    [720, 338],
    [880, 338],
    [1100, 260],
    [1440, 170],
  ],
] as const;

const CURVE_POINTS = CURVE.flatMap((segment) =>
  Array.from({ length: 121 }, (_, index) => {
    const t = index / 120;
    const u = 1 - t;
    const weights = [u * u * u, 3 * u * u * t, 3 * u * t * t, t * t * t];

    return {
      x: segment.reduce((sum, point, at) => sum + point[0] * weights[at], 0),
      y: segment.reduce((sum, point, at) => sum + point[1] * weights[at], 0),
    };
  }),
);

/** The curve's height at a fraction of the band's width. */
function curveAt(fraction: number) {
  const x = fraction * 1440;

  const next = Math.max(
    1,
    CURVE_POINTS.findIndex((point) => point.x >= x),
  );

  const a = CURVE_POINTS[next - 1];
  const b = CURVE_POINTS[next];

  return a.y + (b.y - a.y) * ((x - a.x) / (b.x - a.x));
}

/** The same sequence every time, so the sky never reshuffles between visits. */
function seeded(seed: number) {
  let state = seed;

  return () => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;

    return state / 4294967296;
  };
}

function drawRays(width: number) {
  const random = seeded(11);
  const rays: Ray[] = [];

  for (let x = 8; x < width - 12; x += 2.5 + random() * 8) {
    const side = Math.abs(x / width - 0.5) * 2;
    const base = curveAt(x / width) + (random() - 0.5) * 10;
    const height = 56 + random() * 150 + (1 - side) * 110 * random();
    const rayWidth = 0.6 + random() * (random() < 0.1 ? 8 : 2.2);
    const opacity = (0.14 + random() * 0.56) * (1 - Math.pow(side, 3) * 0.75);

    rays.push({ height, opacity, width: rayWidth, x, y: base - height });
  }

  return rays;
}

function drawStars(width: number, height: number) {
  const random = seeded(5);
  const stars: Star[] = [];
  const count = Math.round((width * height) / 5200);

  for (let index = 0; index < count; index++) {
    const x = 8 + random() * (width - 16);
    const y = Math.pow(random(), 1.3) * height * 0.94;
    const big = random() < 0.03;
    const opacity = (0.25 + random() * 0.6) * (0.2 + 0.8 * (1 - y / height));

    stars.push({ big, opacity, radius: big ? 1.25 : 0.35 + random() * 0.7, x, y });
  }

  return stars;
}

/**
 * Lays the aurora and the horizon behind the waitlist card and draws the stars and rays at the
 * hero's real size, so nothing stretches. The hero carries --band-y and --horizon, and
 * data-tight when the card leaves too little room for the scroll hint.
 */
export function useHeroArt(
  heroRef: RefObject<HTMLElement | null>,
  cardRef: RefObject<HTMLElement | null>,
) {
  const [art, setArt] = useState<Art | null>(null);

  useEffect(() => {
    const hero = heroRef.current;
    const card = cardRef.current;

    if (!hero || !card) return;

    let frame = 0;

    const layout = () => {
      const height = hero.offsetHeight;
      const width = hero.offsetWidth;
      const top = card.offsetTop;
      const cardHeight = card.offsetHeight;
      // On phones the card fills the width: the aurora's arms end level with its top edge, so
      // only the rays rise above it.
      const narrow = width <= 560;
      const band = parseFloat(getComputedStyle(hero).getPropertyValue('--band-h'));
      const bandY = narrow ? top - 16 + band * 0.25 : top + cardHeight / 2;
      const horizon = Math.round(Math.min(height - 40, top + cardHeight * (narrow ? 0.6 : 0.72)));

      hero.style.setProperty('--band-y', `${Math.round(bandY)}px`);
      hero.style.setProperty('--horizon', `${horizon}px`);
      hero.toggleAttribute('data-tight', height - (top + cardHeight) < 104);
      setArt((drawn) =>
        drawn && Math.abs(width - drawn.width) <= 24 && Math.abs(horizon - drawn.horizon) <= 24
          ? drawn
          : {
              rays: drawn && Math.abs(width - drawn.width) <= 24 ? drawn.rays : drawRays(width),
              stars: drawStars(width, horizon),
              width,
              horizon,
            },
      );
    };

    const schedule = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(layout);
    };

    const resize = new ResizeObserver(schedule);

    resize.observe(hero);
    resize.observe(card);
    void document.fonts?.ready.then(schedule);
    layout();

    // The rays sway only while the hero is on screen.
    const away = new IntersectionObserver(([entry]) =>
      hero.toggleAttribute('data-away', !entry.isIntersecting),
    );

    away.observe(hero);

    return () => {
      cancelAnimationFrame(frame);
      resize.disconnect();
      away.disconnect();
    };
  }, [cardRef, heroRef]);

  return art;
}

