'use client';

import { useEffect, useRef, useState } from 'react';
import { motionReduced } from '../../lib/liquid-motion';

/**
 * A figure that counts to `target` with an ease-out, from `from` when given or else from the
 * figure it shows. Reduced motion sets it at once.
 */
export function useCountTo(target: number, duration: number, from?: number, delay = 0) {
  const [value, setValue] = useState(target);
  const shown = useRef(target);

  useEffect(() => {
    const begin = from ?? shown.current;
    let frame = 0;

    const step = (start: number) => (now: number) => {
      const progress =
        motionReduced() || begin === target
          ? 1
          : Math.min(1, Math.max(0, (now - start) / duration));

      const next = Math.round(begin + (target - begin) * (1 - Math.pow(1 - progress, 3)));

      shown.current = next;
      setValue(next);

      if (progress < 1) frame = requestAnimationFrame(step(start));
    };

    frame = requestAnimationFrame(step(performance.now() + delay));

    return () => cancelAnimationFrame(frame);
  }, [delay, duration, from, target]);

  return value;
}

/*
  Halcyon, a Glassy UI template. Every rule is scoped to .halcyon. Set --halcyon-accent,
  --halcyon-accent-rotate, --halcyon-accent-ink, --halcyon-serif and --halcyon-sans on any
  ancestor to change the accent and the fonts.
*/

.halcyon {
  --hc-accent: var(--halcyon-accent, #3ad1e0);
  --hc-accent-soft: color-mix(in srgb, var(--hc-accent) 45%, #fff);
  --hc-accent-ink: var(--halcyon-accent-ink, #062a30);
  --hc-serif: var(--halcyon-serif, ui-serif, Georgia, 'Times New Roman', serif);
  --hc-sans: var(
    --halcyon-sans,
    -apple-system,
    BlinkMacSystemFont,
    'Segoe UI',
    system-ui,
    sans-serif
  );
  --hc-navy: #0e1424;
  --hc-ink: #f3f5fa;
  --hc-ink-2: #b9c1d2;
  --hc-ink-3: #959fb4;
  --hc-rose: #ff9aac;
  --hc-line: rgb(255 255 255 / 0.1);
  --hc-wrap: 1200px;
  --hc-gutter: 24px;
  --hc-ease-in: cubic-bezier(0.5, 0, 0.75, 0);

  /* The library's tokens, in Halcyon's night and aqua. */
  --lg-foreground: var(--hc-ink);
  --lg-muted-foreground: var(--hc-ink-2);
  --lg-accent: var(--hc-accent);
  --lg-accent-foreground: var(--hc-accent-ink);
  --lg-prominent-fill: var(--hc-accent);
  /* Recolours whatever sits behind a prominent button into a light aqua, so its dark label
     keeps 7:1 or more. */
  --lg-prominent-tint: grayscale(1) contrast(0.12) brightness(1) sepia(1)
    hue-rotate(var(--halcyon-accent-rotate, 136deg)) saturate(2.8) brightness(1.22);
  --lg-prominent-glow: 210 250 255;
  --lg-prominent-shade: 2 30 36;
  --lg-switch-on: var(--hc-accent);
  --lg-focus-ring: var(--hc-accent-soft);
  --lg-invalid: var(--hc-rose);
  --lg-control-surface: rgb(4 8 20 / 0.44);
  --lg-control-surface-hover: rgb(4 8 20 / 0.62);
  --lg-border: rgb(255 255 255 / 0.12);
  --lg-overlay-surface: rgb(17 24 44 / 0.84);
  --lg-header-tint: rgb(14 20 36 / 0.42);

  color: var(--hc-ink);
  font-family: var(--hc-sans);
  letter-spacing: normal;
}

@layer base {
  .halcyon :where(h1, h2, h3, p, ul, blockquote, figure, dl, dd) {
    margin: 0;
    padding: 0;
  }

  .halcyon :where(ul) {
    list-style: none;
  }

  .halcyon :where(a) {
    color: inherit;
  }

  .halcyon :where(em) {
    font-style: italic;
  }
}

html:has(.halcyon-page) {
  background: #0e1424;
  scroll-padding-top: 96px;
}

@media (prefers-reduced-motion: no-preference) {
  html:has(.halcyon-page) {
    scroll-behavior: smooth;
  }
}

.halcyon-page {
  position: relative;
  min-height: 100vh;
  min-width: 320px;
  overflow-x: clip;
  background: var(--hc-navy);
  font-size: 17px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.halcyon-defs {
  position: absolute;
}

.halcyon-icon {
  display: block;
  width: 18px;
  height: 18px;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.halcyon-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

.halcyon :where(a, summary, [tabindex]:not([tabindex='-1'])):focus-visible,
.halcyon-footer-link:focus-visible,
.halcyon-waitlist-reset:focus-visible {
  outline: 2px solid var(--hc-accent-soft);
  outline-offset: 3px;
}

.halcyon [tabindex='-1']:focus {
  outline: none;
}

.halcyon-skip {
  position: fixed;
  top: 12px;
  left: 16px;
  z-index: 90;
  padding: 10px 16px;
  border-radius: 999px;
  background: var(--hc-ink);
  color: var(--hc-navy);
  font-weight: 600;
  text-decoration: none;
  transform: translateY(-180%);
}

.halcyon-skip:focus {
  transform: none;
}

.halcyon-wrap {
  width: min(var(--hc-wrap), 100% - var(--hc-gutter) * 2);
  margin-inline: auto;
}

.halcyon-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--hc-accent-soft);
  font: 600 14px/1.3 var(--hc-sans);
  letter-spacing: 0.01em;
}

.halcyon-section-title {
  font: 400 clamp(40px, 2.8vw + 22px, 64px) / 1.02 var(--hc-serif);
  letter-spacing: -0.022em;
  text-wrap: balance;
}

.halcyon-section-title em,
.halcyon-footer-title em,
.halcyon-note-quote em,
.halcyon-doc-title em {
  color: var(--hc-accent-soft);
}

.halcyon-section-lede {
  max-width: 52ch;
  color: var(--hc-ink-2);
  font-size: 18px;
  text-wrap: pretty;
}

.halcyon-section-lede a {
  color: var(--hc-ink);
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-color: color-mix(in srgb, var(--hc-accent-soft) 50%, transparent);
}

.halcyon-section-lede a:hover {
  text-decoration-color: var(--hc-accent-soft);
}

/* Panes take the night's navy into their frost, as the page's own glass. */
.halcyon-pane::before {
  background-color: rgb(20 28 52 / 0.42);
}

/* Buttons: the library's slabs at Halcyon's sizes. */
.halcyon-button-xl {
  min-height: 56px;
  padding: 0 26px;
  font-size: 17px;
  font-weight: 600;
}

.halcyon-button-lg {
  min-height: 48px;
  padding: 0 22px;
  font-size: 16px;
  font-weight: 600;
}

/* Header */
.halcyon-header {
  font-family: var(--hc-sans);
}

/* A shallow rim keeps large scrolling type from stretching across the whole capsule. */
.halcyon-header > .lg-header-glass {
  --lg-lens-bevel: 7;
  --lg-lens-thickness: 24;
  --lg-lens-dispersion: 0;
  --lg-slab-blur: 8;
  --lg-header-tint: rgb(14 20 36 / 0.54);
  --lg-lens-saturation: 1.1;
}

.halcyon-brand {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--hc-ink);
  text-decoration: none;
  border-radius: 10px;
}

.halcyon-brand-mark {
  width: 30px;
  height: 30px;
}

.halcyon-brand-name {
  font: 400 27px/1 var(--hc-serif);
  letter-spacing: -0.01em;
}

.halcyon-brand-small {
  font-size: 23px;
}

.halcyon-brand:has(.halcyon-brand-small) {
  gap: 8px;
}

.halcyon-brand:has(.halcyon-brand-small) .halcyon-brand-mark {
  width: 26px;
  height: 26px;
}

.halcyon-header .lg-header-actions {
  gap: 8px;
}

/* The header's join button appears only while no other primary action is on screen. */
.halcyon-header-join {
  translate: 0 -8px;
  visibility: hidden;
  transition:
    translate 200ms var(--hc-ease-in),
    visibility 0s linear 200ms,
    --lg-button-rise var(--lg-button-rise-time) var(--lg-ease-out);
}

.halcyon-header[data-join] .halcyon-header-join {
  translate: none;
  visibility: visible;
  transition:
    translate 520ms var(--lg-spring),
    visibility 0s,
    --lg-button-rise var(--lg-button-rise-time) var(--lg-ease-out);
}

/* Hero */
.halcyon-hero {
  --band-h: 600px;
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 100vh;
  min-height: 100svh;
  padding: 112px 0 124px;
  overflow: clip;
}

.halcyon-hero-art {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
}

.halcyon-hero-sky {
  position: absolute;
  inset: 0 0 auto;
  height: var(--horizon, 80%);
  background:
    radial-gradient(
      52% 58% at 50% 100%,
      rgb(255 179 138 / 0.36),
      rgb(255 179 138 / 0.12) 44%,
      transparent 74%
    ),
    radial-gradient(28% 26% at 50% 100%, rgb(255 222 204 / 0.3), transparent 72%),
    linear-gradient(
      180deg,
      #080d1a 0%,
      #0c1222 32%,
      #111a33 60%,
      #1c2242 82%,
      #2c2a4a 94%,
      #3a3150 100%
    );
}

.halcyon-hero-stars {
  position: absolute;
  inset: 0 0 auto;
  display: block;
  width: 100%;
  height: var(--horizon, 80%);
}

.halcyon-aurora {
  position: absolute;
  left: 0;
  width: 100%;
  top: calc(var(--band-y, 62%) - var(--band-h) / 2);
  height: var(--band-h);
  -webkit-mask: linear-gradient(180deg, transparent, #000 30%, #000 82%, transparent);
  mask: linear-gradient(180deg, transparent, #000 30%, #000 82%, transparent);
}

.halcyon-aurora svg {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.halcyon-aurora-rays {
  transform-origin: 50% 56%;
  will-change: transform;
}

.halcyon-hero-sea {
  position: absolute;
  inset: var(--horizon, 80%) 0 0;
  background:
    radial-gradient(34% 44% at 50% 0%, rgb(255 179 138 / 0.26), transparent 72%),
    radial-gradient(
      70% 60% at 50% 0%,
      color-mix(in srgb, var(--hc-accent) 10%, transparent),
      transparent 74%
    ),
    linear-gradient(180deg, #1f2342 0%, #151c36 34%, #0f1628 100%);
}

.halcyon-hero-sea::after {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(180deg, rgb(255 226 210 / 0.08) 0 1px, transparent 1px 7px);
  -webkit-mask: radial-gradient(56% 100% at 50% 0%, #000 10%, transparent 78%);
  mask: radial-gradient(56% 100% at 50% 0%, #000 10%, transparent 78%);
}

.halcyon-hero-horizon {
  position: absolute;
  left: 0;
  right: 0;
  top: var(--horizon, 80%);
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    rgb(255 205 180 / 0.5) 22%,
    rgb(255 242 234 / 0.95) 50%,
    rgb(255 205 180 / 0.5) 78%,
    transparent
  );
  box-shadow: 0 0 22px 3px rgb(255 179 138 / 0.26);
}

.halcyon-hero-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.halcyon-hero-chip {
  margin-bottom: 28px;
  padding: 5px 12px;
  font-size: 13px;
  line-height: 18px;
}

.halcyon-hero-chip .lg-badge-dot {
  background: var(--hc-accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--hc-accent) 18%, transparent);
}

.halcyon-hero-title {
  font: 400 min(clamp(52px, 15vw + 10px, 128px), 15vh) / 0.92 var(--hc-serif);
  letter-spacing: -0.028em;
  text-wrap: balance;
}

.halcyon-line {
  display: block;
}

/* The padding keeps the italic f inside the clipped gradient; the larger negative margin tucks
   the full stop back under its overhang. */
.halcyon-hero-title em {
  margin-right: -0.13em;
  padding-right: 0.07em;
  letter-spacing: -0.03em;
  background: linear-gradient(
    100deg,
    #f1fdfe 8%,
    var(--hc-accent-soft) 46%,
    color-mix(in srgb, var(--hc-accent) 72%, #fff) 96%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.halcyon-hero-sub {
  max-width: 34ch;
  margin-top: 26px;
  color: var(--hc-ink-2);
  font-size: clamp(17px, 0.45vw + 15px, 21px);
  line-height: 1.48;
  text-wrap: balance;
}

.halcyon-hero-more {
  position: absolute;
  left: 50%;
  bottom: 24px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 999px;
  translate: -50% 0;
  color: var(--hc-ink-2);
  font: 500 14px/1 var(--hc-sans);
  text-decoration: none;
  transition: color 200ms var(--lg-ease-out);
}

.halcyon-hero-more .halcyon-icon {
  width: 16px;
  height: 16px;
  transition: transform 320ms var(--lg-spring);
}

.halcyon-hero-more:hover {
  color: var(--hc-ink);
}

.halcyon-hero-more:hover .halcyon-icon {
  transform: translateY(3px);
}

.halcyon-hero[data-tight] .halcyon-hero-more {
  display: none;
}

/* The waitlist: two states share one pane, and their rows roll through it like a ticket
   counter. */
.halcyon-waitlist-slot {
  position: relative;
  width: min(600px, 100%);
  margin-top: 44px;
}

.halcyon-waitlist {
  --lg-panel-radius: 32px;
  --halcyon-travel: 240px;
  --wl-pad: 16px;
  padding: 0;
  text-align: left;
}

/* Keep the face clear; the narrow lens carries the thickness at the rim. */
.halcyon-waitlist {
  --lg-glass-thickness: 1;
  --lg-lens-bevel: 18;
  --lg-lens-thickness: 64;
  --lg-lens-depth: 1;
  --lg-lens-ior: 1.5;
  --lg-lens-blur: 0.75;
  --lg-lens-dispersion: 0;
}

.halcyon-waitlist::before {
  background-color: rgb(12 20 38 / 0.12);
}

.halcyon-waitlist-submit {
  --lg-accent-foreground: #e7fbff;
  --lg-prominent-tint: saturate(0.85) brightness(1.05);
  --lg-lens-bevel: 10;
  --lg-lens-thickness: 28;
  --lg-lens-blur: 0.5;
  --lg-lens-dispersion: 0;
}

.halcyon-waitlist-submit > .lg-button__layers > .lg-button__distortion {
  background: rgb(6 28 38 / 0.55);
}

.halcyon-waitlist-submit > .lg-button__layers > .lg-button__light {
  background: rgb(2 30 36 / 0.12);
  box-shadow: none;
}

.halcyon-waitlist-submit > .lg-button__layers > .lg-button__tint {
  box-shadow: inset 0 0 0 1px rgb(211 249 255 / 0.18);
}

.halcyon-waitlist-submit > .lg-button__layers > .lg-button__rim {
  opacity: 0.35;
}

.halcyon-waitlist-clip {
  display: grid;
  padding: 18px var(--wl-pad) var(--wl-pad);
  border-radius: inherit;
  overflow: hidden;
}

.halcyon-waitlist-state {
  grid-area: 1 / 1;
  display: grid;
  align-content: space-between;
  row-gap: 14px;
  min-width: 0;
}

.halcyon-waitlist-row {
  --i: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  transition:
    transform 760ms var(--lg-spring) calc(170ms + var(--i) * 60ms),
    visibility 0s linear calc(170ms + var(--i) * 60ms);
}

.halcyon-waitlist-row[data-row='1'] {
  --i: 1;
}

.halcyon-waitlist-row[data-row='2'] {
  --i: 2;
}

.halcyon-waitlist[data-state='form'] .halcyon-waitlist-done .halcyon-waitlist-row,
.halcyon-waitlist[data-state='done'] .halcyon-waitlist-form .halcyon-waitlist-row {
  visibility: hidden;
  transition:
    transform 260ms var(--hc-ease-in) calc(var(--i) * 28ms),
    visibility 0s linear calc(260ms + var(--i) * 28ms);
}

.halcyon-waitlist[data-state='form'] .halcyon-waitlist-done .halcyon-waitlist-row {
  transform: translateY(var(--halcyon-travel));
}

.halcyon-waitlist[data-state='done'] .halcyon-waitlist-form .halcyon-waitlist-row {
  transform: translateY(calc(var(--halcyon-travel) * -1));
}

.halcyon-waitlist-top {
  justify-content: space-between;
  min-height: 30px;
  padding-inline: 8px 6px;
}

.halcyon-waitlist-label {
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.005em;
}

.halcyon-waitlist-meta {
  color: var(--hc-ink-2);
  font-size: 14px;
}

.halcyon-waitlist-entry > div,
.halcyon-copy-box > div {
  flex: 1;
  min-width: 0;
}

.halcyon-waitlist-input,
.halcyon-copy-input {
  height: 56px;
  border-radius: 999px;
  font-size: 17px;
}

.halcyon-waitlist-input {
  padding-inline: 22px;
}

.halcyon-waitlist-submit,
.halcyon-copy-button {
  flex: none;
  min-width: 202px;
}

.halcyon-waitlist-spinner {
  --lg-spinner-color: var(--hc-accent-ink);
  color: var(--hc-accent-ink);
}

.halcyon-waitlist-foot {
  justify-content: space-between;
  min-height: 30px;
  padding-inline: 8px 6px;
}

.halcyon-waitlist-foot-form {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
}

.halcyon-waitlist-foot-form > * {
  grid-area: 1 / 1;
}

.halcyon-waitlist-proof {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 6px 14px;
  transition:
    transform 320ms var(--lg-ease-out),
    opacity 200ms var(--lg-ease-out),
    visibility 0s;
}

.halcyon-waitlist-hint {
  color: var(--hc-ink-2);
  font-size: 14px;
}

.halcyon-waitlist-error {
  align-self: center;
  color: var(--hc-rose);
  font-size: 14px;
  font-weight: 500;
  opacity: 0;
  visibility: hidden;
  transform: translateY(8px);
  transition:
    transform 320ms var(--lg-ease-out),
    opacity 200ms var(--lg-ease-out),
    visibility 0s linear 200ms;
}

.halcyon-waitlist[data-invalid] .halcyon-waitlist-error {
  opacity: 1;
  visibility: visible;
  transform: none;
  transition:
    transform 420ms var(--lg-spring),
    opacity 200ms var(--lg-ease-out),
    visibility 0s;
}

.halcyon-waitlist[data-invalid] .halcyon-waitlist-proof {
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition:
    transform 200ms var(--hc-ease-in),
    opacity 160ms var(--hc-ease-in),
    visibility 0s linear 160ms;
}

.halcyon-waitlist-check {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  flex: none;
  border-radius: 50%;
  background: var(--hc-accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--hc-accent) 16%, transparent);
}

.halcyon-waitlist-check svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: var(--hc-accent-ink);
  stroke-width: 2.3;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 20;
}

.halcyon-waitlist-place {
  flex: 1;
  min-width: 0;
  font: 400 29px/1.05 var(--hc-serif);
  letter-spacing: -0.012em;
  white-space: nowrap;
}

.halcyon-waitlist-place strong {
  color: var(--hc-accent);
  font-weight: 400;
  font-variant-numeric: tabular-nums;
}

.halcyon-waitlist-reset {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 10px;
  border: 0;
  border-radius: 999px;
  background: none;
  color: var(--hc-ink-2);
  font: 500 14px/1 var(--hc-sans);
  cursor: pointer;
  transition: color 160ms var(--lg-ease-out);
}

.halcyon-waitlist-reset:hover {
  color: var(--hc-ink);
}

.halcyon-waitlist-reset .halcyon-icon {
  width: 16px;
  height: 16px;
}

.halcyon-waitlist-progress {
  flex: none;
  width: 104px;
}

.halcyon-waitlist-move {
  flex: 1;
  min-width: 0;
  color: var(--hc-ink-2);
  font-size: 14px;
}

.halcyon-waitlist-count {
  color: var(--hc-ink);
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.halcyon-waitlist-demo {
  position: absolute;
  top: calc(100% + 14px);
  left: 0;
  right: 0;
  color: var(--hc-ink-2);
  font-size: 14px;
  text-align: center;
}

/* A prominent button's glass recolours the page behind it. The sheet frosts its own backdrop,
   and in Safari and Firefox the glass here may see little or none of the page, so its face
   would show only the dark light under it, behind a dark label. There it takes the solid fill
   instead, as the library does where glass cannot be drawn. */
.halcyon-sheet .lg-button--prominent > .lg-button__layers > .lg-button__distortion {
  background-color: var(--lg-prominent-fill);
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}

@supports not (-webkit-app-region: drag) {
  .halcyon .lg-button--prominent > .lg-button__layers > .lg-button__distortion {
    background-color: var(--lg-prominent-fill);
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }
}

/* AvatarStack */
.halcyon-avatars {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.halcyon-avatars-list {
  display: inline-flex;
  padding-left: 5px;
}

.halcyon-avatars-item {
  position: relative;
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  margin-left: -5px;
  border-radius: 50%;
  color: #fff;
  font: 600 10px/1 var(--hc-sans);
  box-shadow: 0 0 0 1.5px #161d35;
}

.halcyon-avatars-item:nth-child(1) {
  z-index: 4;
}

.halcyon-avatars-item:nth-child(2) {
  z-index: 3;
}

.halcyon-avatars-item:nth-child(3) {
  z-index: 2;
}

.halcyon-avatars-item:nth-child(4) {
  z-index: 1;
}

.halcyon-avatars-text {
  color: var(--hc-ink-2);
  font-size: 14px;
  white-space: nowrap;
}

.halcyon-avatars-text strong {
  color: var(--hc-ink);
  font-weight: 600;
}

/* The invite link */
.halcyon-copy-box {
  position: relative;
  display: flex;
  flex: 1;
  min-width: 0;
}

.halcyon-copy-icon {
  position: absolute;
  z-index: 3;
  top: 50%;
  left: 20px;
  margin-top: -9px;
  color: var(--hc-accent-soft);
  pointer-events: none;
}

.halcyon-copy-input {
  padding: 0 18px 0 48px;
  font-size: 16px;
  text-overflow: ellipsis;
  cursor: text;
}

.halcyon-copy-input::selection {
  background: color-mix(in srgb, var(--hc-accent) 38%, transparent);
}

.halcyon-copy-glyphs,
.halcyon-copy-labels {
  display: inline-grid;
}

.halcyon-copy-glyphs > *,
.halcyon-copy-labels > * {
  grid-area: 1 / 1;
}

.halcyon-copy-glyph-done,
.halcyon-copy-label-done,
.halcyon-copy-button[data-copied] .halcyon-copy-glyph,
.halcyon-copy-button[data-copied] .halcyon-copy-label {
  visibility: hidden;
}

.halcyon-copy-button[data-copied] .halcyon-copy-glyph-done,
.halcyon-copy-button[data-copied] .halcyon-copy-label-done {
  visibility: visible;
}

/* What it will do */
.halcyon-what {
  position: relative;
  isolation: isolate;
  overflow: clip;
}

.halcyon-what-scene {
  padding: clamp(80px, 8vw, 120px) 0 clamp(64px, 6vw, 96px);
}

/* One image-backed field draws the three outer lenses; the CSS dawn remains for first paint. */
.halcyon-what-scene[data-lg-scene-renderer='webgl'] > .halcyon-what-art {
  display: none;
}

.halcyon-what-scene .halcyon-tile {
  --lg-scene-tint: rgb(20 28 52 / 0.42);
  --lg-scene-frost: 1px;
  --lg-scene-ink: var(--hc-ink-2);
}

/* Controls sit on an already frosted slab, without filtering the same backdrop again. */
.halcyon-tile-screen .lg-button__distortion,
.halcyon-books-length::before,
.halcyon-books-length > .lg-segmented-indicator {
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}

.halcyon-what-art {
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(
      36% 30% at 14% 56%,
      color-mix(in srgb, var(--hc-accent) 17%, transparent),
      transparent 72%
    ),
    radial-gradient(32% 28% at 88% 70%, rgb(255 179 138 / 0.14), transparent 72%),
    linear-gradient(180deg, #0f1628 0%, #0e1424 36%);
}

.halcyon-what-art::before {
  content: '';
  position: absolute;
  inset: 22% 0 4%;
  background: repeating-linear-gradient(180deg, rgb(190 240 245 / 0.09) 0 1px, transparent 1px 9px);
  -webkit-mask: radial-gradient(72% 62% at 50% 52%, #000 28%, transparent 76%);
  mask: radial-gradient(72% 62% at 50% 52%, #000 28%, transparent 76%);
}

/* A second dawn line runs behind the tiles, where screen meets copy, so each lens rim has a
   horizon to bend. */
.halcyon-what-art::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  top: calc(var(--halcyon-what-line, 58%) - 110px);
  height: 220px;
  background:
    radial-gradient(38% 46% at 50% 50%, rgb(255 179 138 / 0.17), transparent 72%),
    radial-gradient(
      64% 30% at 50% 50%,
      color-mix(in srgb, var(--hc-accent) 17%, transparent),
      transparent 76%
    );
}

.halcyon-what-horizon {
  position: absolute;
  left: 0;
  right: 0;
  top: var(--halcyon-what-line, 58%);
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent 1%,
    color-mix(in srgb, var(--hc-accent-soft) 60%, transparent) 18%,
    rgb(255 242 234) 50%,
    color-mix(in srgb, var(--hc-accent-soft) 60%, transparent) 82%,
    transparent 99%
  );
  box-shadow: 0 0 22px 3px color-mix(in srgb, var(--hc-accent) 30%, transparent);
}

.halcyon-section-head {
  display: grid;
  justify-items: center;
  gap: 16px;
  max-width: 700px;
  margin: 0 auto clamp(48px, 5vw, 72px);
  text-align: center;
}

.halcyon-what-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0 20px;
}

.halcyon-tile {
  --lg-panel-radius: 30px;
  display: grid;
  grid-row: span 2;
  grid-template-rows: subgrid;
  row-gap: 0;
  padding: 12px 12px 28px;
}

.halcyon-tile-screen {
  grid-row: 1;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px;
  border-radius: 20px;
  background: rgb(4 8 20 / 0.38);
  box-shadow:
    inset 0 0 0 1px rgb(255 255 255 / 0.07),
    inset 0 1px 0 rgb(255 255 255 / 0.04);
}

.halcyon-tile-body {
  grid-row: 2;
  padding: 24px 14px 0;
}

.halcyon-tile-kicker {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--hc-accent-soft);
  font: 600 14px/1 var(--hc-sans);
}

.halcyon-tile h3 {
  margin-top: 12px;
  font: 400 27px/1.1 var(--hc-serif);
  letter-spacing: -0.012em;
  text-wrap: balance;
}

.halcyon-tile-body > p:last-child {
  margin-top: 10px;
  color: var(--hc-ink-2);
  font-size: 16px;
  text-wrap: pretty;
}

.halcyon-mini-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 32px;
}

.halcyon-mini-title {
  font-size: 14px;
  font-weight: 600;
}

.halcyon-mini-status {
  min-height: 20px;
  margin-top: auto;
  color: var(--hc-ink-2);
  font-size: 13px;
  line-height: 1.45;
  text-wrap: pretty;
}

.halcyon-status > span {
  display: block;
}

.halcyon-books-who {
  justify-content: flex-start;
  color: var(--hc-ink-2);
  font-size: 14px;
  line-height: 1.3;
  text-wrap: pretty;
}

.halcyon-books-who strong {
  color: var(--hc-ink);
  font-weight: 600;
}

.halcyon-books-avatar {
  flex: none;
}

.halcyon-avatar-teal .lg-avatar-fallback,
.halcyon-books-avatar .lg-avatar-fallback {
  background: linear-gradient(140deg, #1b7f8a, #22407a);
  color: #fff;
}

.halcyon-avatar-violet .lg-avatar-fallback {
  background: linear-gradient(140deg, #5a4bb0, #26306e);
  color: #fff;
}

.halcyon-books-length {
  width: 100%;
}

.halcyon-books-length .lg-segmented-item {
  flex: 1;
  padding-inline: 6px;
  font-size: 13.5px;
}

.halcyon-books-slots {
  display: grid;
  gap: 8px;
}

.halcyon-books-slot {
  width: 100%;
  height: 44px;
  padding: 0 16px;
  font-size: 14px;
  font-weight: 500;
}

.halcyon-books-slot .lg-button__label {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
}

.halcyon-books-day {
  color: var(--hc-ink-2);
}

.halcyon-books-time {
  margin-left: auto;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.halcyon-books-tick {
  width: 16px;
  height: 16px;
  color: var(--hc-accent);
  visibility: hidden;
}

.halcyon-books-slot[aria-pressed='true'] {
  --lg-button-fill: color-mix(in srgb, var(--hc-accent) 16%, transparent);
  --lg-button-fill-hover: color-mix(in srgb, var(--hc-accent) 22%, transparent);
  box-shadow: inset 0 0 0 1.5px color-mix(in srgb, var(--hc-accent) 85%, transparent);
}

.halcyon-books-slot[aria-pressed='true'] .halcyon-books-tick {
  visibility: visible;
}

.halcyon-books-slot[aria-pressed='true'] .halcyon-books-day {
  color: var(--hc-accent-soft);
}

.halcyon-calendar {
  --hr: 25px;
  --gap: 5px;
}

.halcyon-calendar-days {
  display: grid;
  grid-template-columns: 22px repeat(3, minmax(0, 1fr));
  column-gap: var(--gap);
  margin-bottom: 6px;
  color: var(--hc-ink-2);
  font-size: 12px;
  font-weight: 600;
}

.halcyon-calendar-body {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  column-gap: var(--gap);
}

.halcyon-calendar-hours {
  position: relative;
  height: calc(var(--hr) * 8);
}

.halcyon-calendar-hours span {
  position: absolute;
  right: 0;
  top: calc(var(--s) * var(--hr) - 6px);
  color: var(--hc-ink-3);
  font-size: 11px;
  line-height: 12px;
  font-variant-numeric: tabular-nums;
}

.halcyon-calendar-grid {
  position: relative;
  height: calc(var(--hr) * 8);
  border-top: 1px solid rgb(255 255 255 / 0.07);
  background: repeating-linear-gradient(
    180deg,
    transparent 0 calc(var(--hr) - 1px),
    rgb(255 255 255 / 0.07) calc(var(--hr) - 1px) var(--hr)
  );
}

.halcyon-event {
  position: absolute;
  top: 0;
  left: 0;
  width: calc((100% - var(--gap) * 2) / 3);
  height: calc(var(--d) * var(--hr) - 3px);
  padding: 4px 7px 0;
  overflow: hidden;
  border-radius: 6px;
  background: color-mix(in srgb, var(--hc-accent) 17%, transparent);
  box-shadow: inset 2px 0 0 var(--hc-accent);
  color: #dcf8fb;
  font: 600 11.5px/14px var(--hc-sans);
  white-space: nowrap;
  text-overflow: ellipsis;
  transform: translate(
    calc(var(--c) * (100% + var(--gap))),
    calc(var(--s) * var(--hr) + 1.5px + var(--dy, 0px))
  );
  transition:
    transform 760ms var(--lg-spring),
    background-color 300ms var(--lg-ease-out),
    box-shadow 300ms var(--lg-ease-out),
    color 300ms var(--lg-ease-out),
    opacity 300ms var(--lg-ease-out);
}

.halcyon-event-focus {
  background: rgb(255 255 255 / 0.06);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--hc-accent-soft) 34%, transparent);
  color: var(--hc-accent-soft);
}

.halcyon-event-focus .halcyon-icon {
  display: inline-block;
  width: 11px;
  height: 11px;
  margin: -2px 3px 0 0;
  vertical-align: middle;
  stroke-width: 2;
}

.halcyon-event-flight {
  --dy: -16px;
  opacity: 0;
  white-space: normal;
  background: repeating-linear-gradient(
    135deg,
    rgb(255 255 255 / 0.13) 0 5px,
    rgb(255 255 255 / 0.04) 5px 10px
  );
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.3);
  color: var(--hc-ink);
}

.halcyon-calendar[data-state='moved'] .halcyon-event-flight {
  --dy: 0px;
  opacity: 1;
}

.halcyon-event.is-conflict {
  z-index: 2;
  background: rgb(255 154 172 / 0.22);
  box-shadow:
    inset 2px 0 0 var(--hc-rose),
    0 0 0 1px rgb(255 154 172 / 0.6);
  color: #ffe5ea;
}

.halcyon-event.is-moved {
  z-index: 2;
  background: color-mix(in srgb, var(--hc-accent) 30%, transparent);
  box-shadow:
    inset 2px 0 0 var(--hc-accent),
    0 0 0 1px color-mix(in srgb, var(--hc-accent) 50%, transparent),
    0 6px 14px -6px color-mix(in srgb, var(--hc-accent) 70%, transparent);
  color: #f1fdfe;
}

.halcyon-calendar[data-still] .halcyon-event {
  transition: none;
}

.halcyon-week-sum {
  color: var(--hc-ink-2);
  font-size: 13px;
}

.halcyon-week-sum strong {
  margin-right: 2px;
  color: var(--hc-accent);
  font: 400 24px/1 var(--hc-serif);
  font-variant-numeric: tabular-nums;
}

.halcyon-week-bars {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}

.halcyon-week-day {
  display: grid;
  justify-items: center;
  gap: 6px;
  color: var(--hc-ink-3);
  font-size: 11.5px;
  font-weight: 600;
}

.halcyon-week-bar {
  position: relative;
  width: 100%;
  height: 92px;
  overflow: hidden;
  border-radius: 8px;
  background: rgb(255 255 255 / 0.05);
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.06);
}

.halcyon-week-zone {
  position: absolute;
  left: 0;
  right: 0;
  background: repeating-linear-gradient(
    135deg,
    color-mix(in srgb, var(--hc-accent) 55%, transparent) 0 3px,
    color-mix(in srgb, var(--hc-accent) 16%, transparent) 3px 7px
  );
  transform: scaleY(0);
  transition: transform 560ms var(--lg-spring);
}

.halcyon-week-am {
  top: 0;
  height: calc(200% / 9);
  transform-origin: 50% 0;
}

.halcyon-week-pm {
  bottom: 0;
  height: calc(200% / 9);
  transform-origin: 50% 100%;
}

.halcyon-week-fri {
  inset: 0;
  transform-origin: 50% 0;
}

.halcyon-week[data-am] .halcyon-week-am,
.halcyon-week[data-pm] .halcyon-week-pm,
.halcyon-week[data-fri] .halcyon-week-fri {
  transform: none;
}

.halcyon-week-meeting {
  position: absolute;
  left: 4px;
  right: 4px;
  top: calc(var(--s) * 100% / 9 + 1px);
  height: calc(var(--d) * 100% / 9 - 2px);
  border-radius: 3px;
  background: rgb(243 245 250 / 0.62);
}

.halcyon-week-rules li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 40px;
  font-size: 14px;
}

.halcyon-week-rules li + li {
  border-top: 1px solid var(--hc-line);
}

/* The founders' note */
.halcyon-note {
  position: relative;
  isolation: isolate;
  padding: clamp(80px, 8vw, 128px) 0;
  overflow: clip;
}

.halcyon-note-art,
.halcyon-faq-art {
  -webkit-mask: linear-gradient(180deg, transparent, #000 18%, #000 82%, transparent);
  mask: linear-gradient(180deg, transparent, #000 18%, #000 82%, transparent);
}

.halcyon-note-art {
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(
      28% 40% at 80% 72%,
      color-mix(in srgb, var(--hc-accent) 13%, transparent),
      transparent 72%
    ),
    radial-gradient(24% 30% at 62% 76%, rgb(255 179 138 / 0.12), transparent 72%);
}

.halcyon-note-art::before {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-radial-gradient(
    circle at 84% 70%,
    transparent 0 43px,
    color-mix(in srgb, var(--hc-accent-soft) 8%, transparent) 43px 44px
  );
  -webkit-mask: radial-gradient(40% 70% at 84% 70%, #000 20%, transparent 80%);
  mask: radial-gradient(40% 70% at 84% 70%, #000 20%, transparent 80%);
}

.halcyon-note-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: 24px;
}

.halcyon-note-side {
  grid-column: 1 / span 3;
  padding-top: 14px;
}

.halcyon-note-body {
  grid-column: 4 / span 9;
}

.halcyon-note-quote p {
  font: 400 clamp(30px, 1.7vw + 20px, 46px) / 1.16 var(--hc-serif);
  letter-spacing: -0.014em;
  text-indent: -0.36em;
  text-wrap: pretty;
}

.halcyon-note-sign {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px 18px;
  margin-top: 40px;
}

.halcyon-note-avatars {
  display: inline-flex;
  padding-left: 10px;
}

.halcyon-note-avatars .lg-avatar {
  margin-left: -10px;
  border-radius: 50%;
  box-shadow: 0 0 0 3px var(--hc-navy);
}

.halcyon-note-names {
  display: grid;
  font-size: 15px;
  line-height: 1.4;
}

.halcyon-note-names span {
  color: var(--hc-ink-2);
}

.halcyon-note-button {
  margin-left: auto;
}

.halcyon-note-button .lg-button__label {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.halcyon-note-button .halcyon-icon {
  width: 16px;
  height: 16px;
  transition: transform 320ms var(--lg-spring);
}

.halcyon-note-button:hover .halcyon-icon {
  transform: translateX(3px);
}

/* StatCounter: the label stays first for screen readers and shows under the figure. */
.halcyon-stats {
  display: grid;
  gap: 26px;
  margin: 44px 0 0;
}

.halcyon-stat {
  display: flex;
  flex-direction: column-reverse;
  gap: 10px;
}

.halcyon-stat + .halcyon-stat {
  padding-top: 26px;
  border-top: 1px solid var(--hc-line);
}

.halcyon-stat dt {
  max-width: 24ch;
  color: var(--hc-ink-2);
  font-size: 14px;
  line-height: 1.45;
  text-wrap: pretty;
}

.halcyon-stat dd {
  margin: 0;
  font: 400 clamp(48px, 1.6vw + 30px, 60px) / 0.95 var(--hc-serif);
  letter-spacing: -0.02em;
  white-space: nowrap;
}

.halcyon-stat-unit {
  margin: 0 0.24em 0 0.06em;
  color: var(--hc-accent-soft);
  font-size: 0.5em;
  font-style: italic;
  letter-spacing: 0;
}

/* Questions */
.halcyon-faq {
  position: relative;
  isolation: isolate;
  padding: clamp(64px, 6vw, 96px) 0;
  overflow: clip;
}

.halcyon-faq-art {
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(
      30% 42% at 68% 38%,
      color-mix(in srgb, var(--hc-accent) 15%, transparent),
      transparent 72%
    ),
    radial-gradient(26% 30% at 90% 70%, rgb(255 179 138 / 0.13), transparent 72%);
}

.halcyon-faq-art::before {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-radial-gradient(
    circle at 72% 46%,
    transparent 0 51px,
    color-mix(in srgb, var(--hc-accent-soft) 8%, transparent) 51px 52px
  );
  -webkit-mask: radial-gradient(42% 64% at 72% 46%, #000 30%, transparent 82%);
  mask: radial-gradient(42% 64% at 72% 46%, #000 30%, transparent 82%);
}

.halcyon-faq-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: 24px;
  align-items: start;
}

.halcyon-faq-intro {
  display: grid;
  justify-items: start;
  gap: 16px;
  grid-column: 1 / span 4;
  padding-top: 8px;
}

.halcyon-faq-intro .halcyon-section-lede {
  text-wrap: balance;
}

.halcyon-faq-list {
  --lg-panel-radius: 30px;
  grid-column: 6 / span 7;
  padding: 6px 28px;
}

.halcyon-faq-item + .halcyon-faq-item {
  border-top: 1px solid var(--hc-line);
}

/* Inside one pane the questions are rows, not glass of their own. */
.halcyon-faq-list .lg-accordion-trigger {
  width: 100%;
  justify-content: space-between;
  gap: 20px;
  padding: 22px 0;
  border: 0;
  border-radius: 12px;
  background: none;
  font: 600 18px/1.35 var(--hc-sans);
  letter-spacing: -0.008em;
  text-align: left;
  text-wrap: balance;
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}

.halcyon-faq-list .lg-accordion-trigger:hover {
  background: none;
}

.halcyon-faq-list .lg-accordion-trigger:focus-visible {
  outline: 2px solid var(--hc-accent-soft);
  outline-offset: 3px;
}

.halcyon-faq-list .lg-accordion-chevron {
  width: 30px;
  height: 30px;
  padding: 7px;
  border-radius: 50%;
  background: rgb(255 255 255 / 0.07);
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.1);
  color: var(--hc-ink);
  transition:
    transform 460ms var(--lg-spring),
    background-color 200ms var(--lg-ease-out);
}

.halcyon-faq-list .lg-accordion-trigger:hover .lg-accordion-chevron {
  background: rgb(255 255 255 / 0.12);
}

.halcyon-faq-list .lg-accordion-trigger[data-state='open'] .lg-accordion-chevron {
  background: color-mix(in srgb, var(--hc-accent) 20%, transparent);
}

.halcyon-faq-list .lg-accordion-content {
  --lg-panel-elevation-shadow: none;
  margin: 0;
  padding: 0 52px 24px 0;
  box-shadow: none;
}

.halcyon-faq-list .lg-accordion-content::before,
.halcyon-faq-list .lg-accordion-content::after {
  display: none;
}

.halcyon-faq-list .lg-accordion-content p {
  max-width: 60ch;
  color: var(--hc-ink-2);
  font-size: 16.5px;
  line-height: 1.6;
}

/* The footer */
.halcyon-footer {
  position: relative;
  isolation: isolate;
  padding: clamp(80px, 8vw, 128px) 0 28px;
  overflow: clip;
  text-align: center;
  view-timeline: --halcyon-footer block;
}

.halcyon-footer-art {
  position: absolute;
  inset: 0;
  z-index: -1;
}

.halcyon-footer-sky {
  position: absolute;
  inset: 0 0 auto;
  height: var(--halcyon-footer-horizon, 52%);
  background:
    radial-gradient(
      44% 64% at 50% 100%,
      rgb(255 179 138 / 0.34),
      rgb(255 179 138 / 0.1) 46%,
      transparent 76%
    ),
    radial-gradient(
      70% 60% at 50% 100%,
      color-mix(in srgb, var(--hc-accent) 12%, transparent),
      transparent 74%
    ),
    linear-gradient(180deg, #0e1424 0%, #131a33 56%, #2a2a49 100%);
}

.halcyon-footer-sky::after {
  content: '';
  position: absolute;
  left: 50%;
  bottom: -150px;
  width: 300px;
  height: 300px;
  margin-left: -150px;
  border-radius: 50%;
  background: radial-gradient(
    circle,
    #ffe2d1 0%,
    #ffc4a3 34%,
    rgb(255 179 138 / 0.5) 50%,
    rgb(255 179 138 / 0.12) 62%,
    rgb(255 179 138 / 0) 72%
  );
}

.halcyon-footer-horizon {
  position: absolute;
  left: 0;
  right: 0;
  top: var(--halcyon-footer-horizon, 52%);
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    rgb(255 205 180 / 0.55) 24%,
    rgb(255 242 234 / 0.95) 50%,
    rgb(255 205 180 / 0.55) 76%,
    transparent
  );
  box-shadow: 0 0 20px 2px rgb(255 179 138 / 0.28);
}

.halcyon-footer-sea {
  position: absolute;
  inset: var(--halcyon-footer-horizon, 52%) 0 0;
  background:
    radial-gradient(30% 34% at 50% 0%, rgb(255 179 138 / 0.24), transparent 72%),
    linear-gradient(180deg, #1e2342 0%, #10172b 44%, #0b1120 100%);
}

.halcyon-footer-sea::after {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(180deg, rgb(255 226 210 / 0.08) 0 1px, transparent 1px 7px);
  -webkit-mask: radial-gradient(44% 60% at 50% 0%, #000 10%, transparent 80%);
  mask: radial-gradient(44% 60% at 50% 0%, #000 10%, transparent 80%);
}

.halcyon-footer-inner {
  display: grid;
  justify-items: center;
}

.halcyon-footer-title {
  margin-bottom: clamp(28px, 2.4vw, 40px);
  font: 400 clamp(36px, 1.6vw + 24px, 52px) / 1.04 var(--hc-serif);
  letter-spacing: -0.02em;
  text-wrap: balance;
}

.halcyon-footer-date {
  margin-top: 30px;
  color: var(--hc-ink-2);
  font-size: 16px;
  text-wrap: balance;
}

.halcyon-footer-date span {
  display: inline-block;
}

.halcyon-footer-action {
  margin-top: 26px;
}

.halcyon-footer-base {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 18px 28px;
  width: 100%;
  margin-top: clamp(96px, 10vw, 140px);
  padding-top: 24px;
  border-top: 1px solid var(--hc-line);
  text-align: left;
}

.halcyon-footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 24px;
}

.halcyon-footer-link {
  padding: 4px 0;
  border: 0;
  background: none;
  color: var(--hc-ink-2);
  font: 500 14px/1.4 var(--hc-sans);
  text-decoration: none;
  cursor: pointer;
  transition: color 160ms var(--lg-ease-out);
}

.halcyon-footer-link:hover {
  color: var(--hc-ink);
}

.halcyon-footer-legal {
  color: var(--hc-ink-3);
  font-size: 13px;
}

/* Countdown */
.halcyon-countdown {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 148px));
  justify-content: center;
  gap: 14px;
  width: 100%;
}

.halcyon-countdown-unit {
  --lg-panel-radius: 26px;
  display: grid;
  justify-items: center;
  gap: 4px;
  padding: 22px 8px 18px;
}

.halcyon-countdown-value {
  display: inline-flex;
  font: 400 clamp(44px, 3.2vw + 22px, 76px) / 1 var(--hc-serif);
  letter-spacing: -0.02em;
}

.halcyon-countdown-slot {
  display: inline-grid;
  width: 0.46em;
  height: 1.06em;
  overflow: hidden;
}

.halcyon-countdown-slot > span {
  grid-area: 1 / 1;
  display: block;
  text-align: center;
}

.halcyon-countdown-label {
  color: var(--hc-ink-2);
  font-size: 13px;
  font-weight: 600;
}

@keyframes halcyon-digit-in {
  from {
    transform: translateY(105%);
  }
}

@keyframes halcyon-digit-out {
  to {
    transform: translateY(-105%);
  }
}

.halcyon-countdown-in {
  animation: halcyon-digit-in 620ms var(--lg-spring) both;
}

.halcyon-countdown-out {
  animation: halcyon-digit-out 260ms var(--hc-ease-in) both;
}

/* The sheet */
.halcyon-sheet {
  color: var(--hc-ink);
}

.halcyon-sheet[data-side='right'] {
  width: min(500px, calc(100vw - 1rem));
}

.halcyon-sheet[data-side='bottom'] {
  max-height: min(88svh, 760px);
}

.halcyon-sheet.lg-glass-surface {
  padding: 0;
}

/* Without the lens the library's light tint leaves the hero's large type legible through the
   note. There the sheet keeps the library's frost over a dense navy fill, which holds the note's
   text at 4.5:1 or more over that type even where an engine draws no backdrop filter. */
@supports not (-webkit-app-region: drag) {
  .halcyon-sheet {
    background: color-mix(in srgb, var(--hc-navy) 90%, transparent);
  }
}

.halcyon-sheet .lg-sheet-handle {
  margin: 0;
}

.halcyon-sheet-head {
  display: flex;
  align-items: center;
  min-height: 64px;
  padding: 14px 64px 4px 24px;
}

.halcyon-sheet-body {
  flex: 1;
  min-height: 0;
}

.halcyon-sheet-body .halcyon-doc {
  padding: 20px 32px 28px;
}

.halcyon-sheet-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 16px 16px 32px;
  border-top: 1px solid var(--hc-line);
}

.halcyon-sheet-foot p {
  color: var(--hc-ink-2);
  font-size: 14px;
}

.halcyon-doc {
  display: grid;
  gap: 16px;
}

.halcyon-doc-title {
  margin: 0 0 4px;
  font: 400 42px/1.02 var(--hc-serif);
  letter-spacing: -0.018em;
  text-wrap: balance;
}

.halcyon-doc p {
  margin: 0;
  color: var(--hc-ink-2);
  font-size: 17px;
  line-height: 1.62;
  text-wrap: pretty;
}

.halcyon-doc .halcyon-eyebrow {
  color: var(--hc-accent-soft);
  font-size: 14px;
}

.halcyon-doc .halcyon-doc-sign {
  margin-top: 8px;
  color: var(--hc-ink);
  font: italic 400 26px/1.2 var(--hc-serif);
}

.halcyon-doc .halcyon-doc-sign span {
  display: block;
  margin-top: 4px;
  color: var(--hc-ink-2);
  font: 400 14px/1.4 var(--hc-sans);
}

/* Toast */
.halcyon-toast .lg-toast-root {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 20px 10px 10px;
}

.halcyon-toast-icon {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  flex: none;
  border-radius: 50%;
  background: var(--hc-accent);
  color: var(--hc-accent-ink);
}

.halcyon-toast-icon .halcyon-icon {
  width: 16px;
  height: 16px;
  stroke-width: 2.2;
}

.halcyon-toast-text {
  color: var(--hc-ink);
  font-size: 15px;
  line-height: 1.38;
  text-wrap: pretty;
}

/* Motion */
@keyframes halcyon-up {
  from {
    transform: translateY(14px);
  }
}

@keyframes halcyon-card {
  from {
    transform: translateY(40px);
  }
}

@keyframes halcyon-dawn {
  from {
    transform: translateY(48px);
  }
}

@keyframes halcyon-breathe {
  from {
    transform: translateY(5px) scaleY(0.94);
  }

  to {
    transform: translateY(-5px) scaleY(1.06);
  }
}

@keyframes halcyon-horizon-in {
  from {
    transform: scaleX(0.1);
  }
}

@keyframes halcyon-sun-rise {
  from {
    transform: translateY(34%);
  }
}

@keyframes halcyon-pop {
  from {
    transform: scale(0.3);
  }
}

@keyframes halcyon-draw {
  from {
    stroke-dashoffset: 20;
  }
}

@keyframes halcyon-focus-in {
  from {
    filter: blur(10px);
    transform: translateY(8px);
  }

  to {
    filter: none;
    transform: none;
  }
}

@keyframes halcyon-rise {
  from {
    transform: translateY(32px);
  }

  to {
    transform: none;
  }
}

@media (prefers-reduced-motion: no-preference) {
  :root:not([data-lg-reduce-motion='1']) .halcyon-hero-chip {
    animation: halcyon-up 900ms var(--lg-ease-out) both;
  }

  :root:not([data-lg-reduce-motion='1']) .halcyon-line {
    animation: halcyon-focus-in 1100ms var(--lg-ease-out) 60ms both;
  }

  :root:not([data-lg-reduce-motion='1']) .halcyon-line + .halcyon-line {
    animation-delay: 170ms;
  }

  :root:not([data-lg-reduce-motion='1']) .halcyon-hero-sub {
    animation: halcyon-focus-in 1000ms var(--lg-ease-out) 280ms both;
  }

  :root:not([data-lg-reduce-motion='1']) .halcyon-waitlist-slot {
    animation: halcyon-card 1100ms var(--lg-ease-out) 380ms both;
  }

  :root:not([data-lg-reduce-motion='1']) .halcyon-aurora {
    animation: halcyon-dawn 1800ms var(--lg-ease-out) both;
  }

  :root:not([data-lg-reduce-motion='1']) .halcyon-hero-horizon {
    animation: halcyon-horizon-in 1600ms var(--lg-ease-out) 120ms both;
  }

  /* The page's one quiet loop: the rays sway over fifteen seconds while the hero is on
     screen. */
  :root:not([data-lg-reduce-motion='1']) .halcyon-aurora-rays {
    animation: halcyon-breathe 15s ease-in-out 1.8s infinite alternate both;
  }

  .halcyon-hero[data-away] .halcyon-aurora-rays {
    animation-play-state: paused;
  }

  :root:not([data-lg-reduce-motion='1']) .halcyon-hero-more {
    animation: halcyon-focus-in 900ms var(--lg-ease-out) 900ms both;
  }

  :root:not([data-lg-reduce-motion='1'])
    .halcyon-waitlist[data-state='done']
    .halcyon-waitlist-check
    svg {
    animation: halcyon-draw 520ms var(--lg-ease-out) 560ms both;
  }

  :root:not([data-lg-reduce-motion='1'])
    .halcyon-copy-button[data-copied]
    .halcyon-copy-glyph-done {
    animation: halcyon-pop 460ms var(--lg-spring);
  }

  :root:not([data-lg-reduce-motion='1']) .halcyon-status > span[data-new] {
    animation: halcyon-focus-in 520ms var(--lg-ease-out) both;
  }

  @supports (animation-timeline: view()) {
    :root:not([data-lg-reduce-motion='1']) .halcyon-reveal-text {
      animation: halcyon-focus-in linear forwards;
      animation-timeline: view();
      animation-range: entry 10% entry 70%;
    }

    /* Panes rise into place as they scroll in; they move only, so their glass keeps its
       backdrop. */
    :root:not([data-lg-reduce-motion='1']) .halcyon-tile,
    :root:not([data-lg-reduce-motion='1']) .halcyon-faq-list {
      animation: halcyon-rise linear both;
      animation-timeline: view();
      animation-range: entry 0% entry 80%;
    }

    /* The footer sun climbs behind the countdown glass as the page reaches it. */
    :root:not([data-lg-reduce-motion='1']) .halcyon-footer-sky::after {
      animation: halcyon-sun-rise linear both;
      animation-timeline: --halcyon-footer;
      animation-range: entry 0% entry 75%;
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .halcyon-waitlist-row,
  .halcyon-waitlist-proof,
  .halcyon-waitlist-error,
  .halcyon-header-join,
  .halcyon-event,
  .halcyon-week-zone,
  .halcyon-hero-more .halcyon-icon,
  .halcyon-note-button .halcyon-icon {
    transition: none !important;
  }

  .halcyon-countdown-slot > span {
    animation: none !important;
  }
}

:root[data-lg-reduce-motion='1']
  :is(
    .halcyon-waitlist-row,
    .halcyon-waitlist-proof,
    .halcyon-waitlist-error,
    .halcyon-header-join,
    .halcyon-event,
    .halcyon-week-zone
  ) {
  transition: none !important;
}

/* Layout */
@media (max-width: 980px) {
  .halcyon-what-grid {
    grid-template-columns: minmax(0, 1fr);
    row-gap: 20px;
    max-width: 560px;
    margin-inline: auto;
  }

  .halcyon-tile {
    grid-row: auto;
    display: flex;
    flex-direction: column;
  }

  .halcyon-tile-screen {
    order: -1;
  }

  .halcyon-faq-intro,
  .halcyon-faq-list {
    grid-column: 1 / -1;
  }

  .halcyon-note-grid {
    display: flex;
    flex-direction: column;
  }

  .halcyon-note-side {
    display: contents;
  }

  .halcyon-note-side .halcyon-eyebrow {
    margin-bottom: 22px;
  }

  .halcyon-stats {
    order: 2;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 20px;
    margin-top: 44px;
    padding-top: 28px;
    border-top: 1px solid var(--hc-line);
  }

  .halcyon-stat + .halcyon-stat {
    padding-top: 0;
    border-top: 0;
  }

  .halcyon-faq-intro {
    margin-bottom: 36px;
  }
}

@media (max-width: 640px) {
  .halcyon-sheet-head {
    min-height: 48px;
    padding: 0 64px 0 20px;
  }

  .halcyon-sheet-body .halcyon-doc {
    padding: 16px 22px 24px;
  }

  .halcyon-sheet-foot {
    padding: 14px 14px 14px 22px;
  }

  .halcyon-doc-title {
    font-size: 36px;
  }
}

@media (max-width: 560px) {
  .halcyon {
    --hc-gutter: 20px;
  }

  .halcyon-brand-name {
    font-size: 25px;
  }

  .halcyon-brand-mark {
    width: 27px;
    height: 27px;
  }

  .halcyon-header-join {
    display: none;
  }

  .halcyon-header[data-join] .halcyon-header-join {
    display: inline-flex;
  }

  .halcyon-header[data-join] .halcyon-header-note {
    display: none;
  }

  .halcyon-hero {
    --band-h: 520px;
    padding: 92px 0 84px;
  }

  .halcyon-aurora {
    -webkit-mask: linear-gradient(180deg, transparent, #000 12%, #000 82%, transparent);
    mask: linear-gradient(180deg, transparent, #000 12%, #000 82%, transparent);
  }

  .halcyon-hero-chip {
    margin-bottom: 22px;
  }

  .halcyon-hero-sub {
    margin-top: 18px;
    font-size: 17px;
  }

  .halcyon-waitlist-slot {
    margin-top: 40px;
  }

  .halcyon-waitlist {
    --lg-panel-radius: 28px;
    --wl-pad: 12px;
  }

  .halcyon-waitlist-clip {
    padding-top: 14px;
  }

  .halcyon-waitlist-state {
    row-gap: 12px;
  }

  .halcyon-waitlist-entry,
  .halcyon-copy {
    flex-direction: column;
    align-items: stretch;
  }

  .halcyon-waitlist-entry > div,
  .halcyon-copy-box {
    flex: none;
  }

  .halcyon-waitlist-submit,
  .halcyon-copy-button {
    width: 100%;
    min-width: 0;
  }

  .halcyon-waitlist-top,
  .halcyon-waitlist-foot {
    padding-inline: 6px 2px;
  }

  .halcyon-waitlist-place {
    font-size: 25px;
  }

  .halcyon-waitlist-reset {
    width: 32px;
    padding: 0;
    justify-content: center;
  }

  .halcyon-waitlist-reset-text {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }

  .halcyon-waitlist-foot-done {
    flex-wrap: wrap;
    row-gap: 8px;
  }

  .halcyon-waitlist-foot-done .halcyon-waitlist-move {
    flex-basis: 100%;
    order: 3;
  }

  .halcyon-waitlist-foot-done .halcyon-waitlist-count {
    margin-left: auto;
  }

  .halcyon-tile {
    --lg-panel-radius: 26px;
    padding: 10px 10px 24px;
  }

  .halcyon-tile-body {
    padding: 20px 10px 0;
  }

  .halcyon-event {
    padding-inline: 6px 4px;
    font-size: 10.5px;
    line-height: 13px;
  }

  .halcyon-note-button {
    margin-left: 0;
  }

  .halcyon-faq-list {
    --lg-panel-radius: 26px;
    padding: 2px 20px;
  }

  .halcyon-faq-list .lg-accordion-trigger {
    padding: 18px 0;
    font-size: 17px;
  }

  .halcyon-faq-list .lg-accordion-content {
    padding-right: 4px;
  }

  .halcyon-countdown {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 8px;
  }

  .halcyon-countdown-unit {
    --lg-panel-radius: 24px;
    padding: 16px 2px 12px;
  }

  .halcyon-countdown-label {
    font-size: 12px;
  }

  .halcyon-footer-base {
    flex-direction: column;
    align-items: flex-start;
  }

  .halcyon-footer-sky::after {
    bottom: -110px;
    width: 220px;
    height: 220px;
    margin-left: -110px;
  }
}

/* Native translate stays at rest immediately when motion or pointing preferences change. */
@media (prefers-reduced-motion: reduce), (hover: none), (pointer: coarse) {
  .halcyon-waitlist,
  .halcyon-what-grid > .halcyon-tile:first-child {
    translate: none !important;
  }
}

:root[data-lg-reduce-motion='1'] .halcyon-waitlist,
:root[data-lg-reduce-motion='1'] .halcyon-what-grid > .halcyon-tile:first-child {
  translate: none !important;
}
